template:
@php
    $shown = array_values(array_filter(is_array($cards) ? $cards : [], static fn ($item): bool => is_array($item) && (trim((string) ($item['title'] ?? '')) !== '' || trim((string) ($item['text'] ?? '')) !== '' || ! empty($item['image']['url']))));
    $across = in_array((string) $columns, ['2', '4'], true) ? (string) $columns : '3';
@endphp
@if ($shown || $heading)
<section class="b-cards b-cards--{{ $across }} b-cards--{{ $pictures === 'icon' ? 'icon' : 'photo' }}" data-wx-block="cards">
    @if ($heading || $intro)
        <div class="b-cards__head">
            @if ($heading)
                <h2 class="b-cards__heading">{{ $heading }}</h2>
            @endif
            @if ($intro)
                <p class="b-cards__intro">{{ $intro }}</p>
            @endif
        </div>
    @endif
    @if ($shown)
        <ul class="b-cards__grid" role="list">
            @foreach ($shown as $card)
                @php
                    $picture = is_array($card['image'] ?? null) && ! empty($card['image']['url']) ? $card['image'] : null;
                    $title = trim((string) ($card['title'] ?? ''));
                    $more = trim((string) ($card['link_label'] ?? ''));
                    $href = trim((string) ($card['link_url'] ?? ''));
                @endphp
                <li @class(['b-cards__card', 'is-linked' => $href !== ''])>
                    @if ($picture)
                        <img class="b-cards__picture" src="{{ $picture['url'] }}" alt="{{ $picture['alt'] ?? '' }}" loading="lazy" @if (! empty($picture['width'])) width="{{ $picture['width'] }}" height="{{ $picture['height'] }}" @endif>
                    @endif
                    <div class="b-cards__body">
                        @if ($title !== '' || ($href !== '' && $more !== ''))
                            <h3 class="b-cards__title">
                                @if ($href !== '')
                                    <a class="b-cards__link" href="{{ $href }}">{{ $title !== '' ? $title : $more }}</a>
                                @else
                                    {{ $title }}
                                @endif
                            </h3>
                        @endif
                        @if (trim((string) ($card['text'] ?? '')) !== '')
                            <p class="b-cards__text">{{ $card['text'] }}</p>
                        @endif
                        @if ($href !== '' && $more !== '' && $title !== '')
                            <span class="b-cards__more" aria-hidden="true">{{ $more }}<x-theme::icon name="arrow-right" class="b-cards__arrow" /></span>
                        @endif
                    </div>
                </li>
            @endforeach
        </ul>
    @endif
</section>
@endif

styles:
.b-cards {
    container-type: inline-size;
    padding-block: var(--site-space-6);
}

.b-cards__head {
    max-width: 42rem;
    margin-bottom: var(--site-space-5);
}

.b-cards__heading {
    margin: 0 0 var(--site-space-2);
}

.b-cards__intro {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-cards__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--site-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-cards__card {
    position: relative;
    display: flex;
    flex-direction: column;
    margin: 0;
    overflow: hidden;
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-lg);
    background: var(--site-color-surface);
    color: var(--site-color-text);
    transition: border-color var(--site-duration) var(--site-easing), box-shadow var(--site-duration) var(--site-easing);
}

.b-cards__card.is-linked:hover {
    border-color: var(--site-color-accent);
    box-shadow: var(--site-shadow-md);
}

.b-cards--photo .b-cards__picture {
    width: 100%;
    max-width: none;
    height: auto;
    aspect-ratio: 3 / 2;
    border-radius: 0;
    object-fit: cover;
}

.b-cards--icon .b-cards__picture {
    width: 3rem;
    height: 3rem;
    margin: var(--site-space-5) var(--site-space-5) 0;
    border-radius: 0;
    object-fit: contain;
}

.b-cards__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--site-space-2);
    padding: var(--site-space-5);
}

.b-cards__title {
    margin: 0;
    font-size: var(--site-font-size-4);
    line-height: 1.3;
    hyphens: auto;
}

.b-cards__link {
    color: inherit;
    text-decoration: none;
}

/* The whole card is the link: the title's box stretched over it, so there is one link to
   tab to and one name for a screen reader. */
.b-cards__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
}

.b-cards__link:focus-visible {
    outline: none;
}

.b-cards__link:focus-visible::after {
    outline: 2px solid var(--site-color-accent);
    outline-offset: -2px;
}

.b-cards__text {
    margin: 0;
    color: var(--site-color-text-muted);
}

.b-cards__more {
    display: flex;
    align-items: center;
    gap: var(--site-space-1);
    margin-top: auto;
    padding-top: var(--site-space-2);
    color: var(--site-color-accent);
    font-weight: 600;
}

.b-cards__arrow {
    transition: transform var(--site-duration) var(--site-easing);
}

.b-cards__card.is-linked:hover .b-cards__arrow {
    transform: translateX(0.25em);
}

@container (min-width: 32rem) {
    .b-cards__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@container (min-width: 52rem) {
    .b-cards--3 .b-cards__grid,
    .b-cards--4 .b-cards__grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@container (min-width: 64rem) {
    .b-cards--4 .b-cards__grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}
